        { "target", name = "Jordan Stilwell" },
        { "goto", x = 52.49, y = 36.92, zone = "1426" },
        { "accept", quest = 1654, text = "Accept The Test of Righteousness" },
        { "target", name = "Jordan Stilwell" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "|cOXP_ENEMY_Bailor Stonehand|r" },
        { "text", text = "|cOXP_ENEMY_Bailor Stonehand|r is downstairs in the house of Thelsamar that has a tailoring merchant outside. His quest only opens once you hold Jordan's." },
        { "goto", x = 35.95, y = 44.91, zone = "1432" },
        { "accept", quest = 1655, text = "Accept Bailor's Ore Shipment" },
        { "target", name = "Bailor Stonehand" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "|cOXP_PICK_Bailor's Ore|r" },
        { "text", text = "The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east Loch Modan, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one." },
        { "goto", x = 71.6, y = 21.61, zone = "1432" },
        { "complete", obj = 1, quest = 1655, text = "Jordan's Ore Shipment: 1 (|cOXP_PICK_Bailor's Ore|r crate)" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "Back to |cOXP_ENEMY_Bailor Stonehand|r" },
        { "text", text = "|cOXP_ENEMY_Bailor Stonehand|r turns the ore into |cOXP_LOOT_Jordan's Refined Ore Shipment|r, the part Jordan wants." },
        { "goto", x = 35.95, y = 44.91, zone = "1432" },
        { "turnin", quest = 1655, text = "Turn in Bailor's Ore Shipment" },
        { "target", name = "Bailor Stonehand" },
        { "goto", x = 35.95, y = 44.91, zone = "1432" },
        { "complete", obj = 2, quest = 1654, text = "Jordan's Refined Ore Shipment: 1" },
        { "mob", name = "Bailor Stonehand" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "|cOXP_LOOT_Whitestone Oak Lumber|r" },
        { "text", text = "Deadmines is a group of five under Moonbrook; the instance portal is at the bottom of the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time." },
        { "reach", text = "Deadmines, in the Moonbrook mine", x = 42.5, y = 71.7, zone = "1436" },
        { "goto", x = 42.5, y = 71.7, zone = "1436" },
        { "complete", obj = 1, quest = 1654, text = "Whitestone Oak Lumber: 1 (Goblin Woodcarvers, inside)" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "|cOXP_LOOT_Jordan's Smithing Hammer|r" },
        { "text", text = "Shadowfang Keep is a dungeon for a group of five in the low to mid 20s, in southern Silverpine Forest, Horde land: a long trip for the Alliance, through the Wetlands, Arathi and Hillsbrad. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it." },
        { "reach", text = "Shadowfang Keep", x = 44.8, y = 67.8, zone = "1421" },
        { "goto", x = 44.8, y = 67.8, zone = "1421" },
        { "complete", obj = 3, quest = 1654, text = "Jordan's Smithing Hammer: 1 (|cOXP_PICK_Jordan's Hammer|r, inside)" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "|cOXP_ENEMY_Thundris Windweaver|r" },
        { "text", text = "|cOXP_ENEMY_Thundris Windweaver|r is in Auberdine. Take his quest before you hunt naga: the Kor Gem never drops without it." },
        { "goto", x = 37.4, y = 40.13, zone = "1439" },
        { "accept", quest = 1442, text = "Accept Seeking the Kor Gem" },
        { "target", name = "Thundris Windweaver" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "The |cOXP_LOOT_Corrupted Kor Gem|r" },
        { "text", text = "The Blackfathom naga in the flooded passages around the Blackfathom Deeps entrance, on Ashenvale's north-west coast, drop the |cOXP_LOOT_Corrupted Kor Gem|r: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group." },
        { "goto", x = 13.55, y = 12.06, zone = "1440" },
        { "complete", obj = 1, quest = 1442, text = "Corrupted Kor Gem: 1" },
        { "mob", name = "Blackfathom Tide Priestess" },
        { "mob", name = "Blackfathom Oracle" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "The |cOXP_LOOT_Purified Kor Gem|r" },
        { "text", text = "Back to |cOXP_ENEMY_Thundris Windweaver|r in Auberdine: he purifies the gem." },
        { "goto", x = 37.4, y = 40.13, zone = "1439" },
        { "turnin", quest = 1442, text = "Turn in Seeking the Kor Gem" },
        { "target", name = "Thundris Windweaver" },
        { "goto", x = 37.4, y = 40.13, zone = "1439" },
        { "complete", obj = 4, quest = 1654, text = "Purified Kor Gem: 1" },
        { "mob", name = "Thundris Windweaver" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/verigans-fist",
        { "text", text = "|cOXP_LOOT_Verigan's Fist|r" },
        { "text", text = "Bring the four parts to |cOXP_FRIENDLY_Jordan Stilwell|r outside Ironforge. Accept his last quest and wait by him while he forges the mace at his anvil." },
        { "goto", x = 52.49, y = 36.92, zone = "1426" },
        { "turnin", quest = 1654, text = "Turn in The Test of Righteousness" },
        { "target", name = "Jordan Stilwell" },
        { "goto", x = 52.49, y = 36.92, zone = "1426" },
        { "accept", quest = 1806, text = "Accept The Test of Righteousness" },
        { "target", name = "Jordan Stilwell" },
        { "goto", x = 52.49, y = 36.92, zone = "1426" },
        { "turnin", quest = 1806, text = "Turn in The Test of Righteousness (|cOXP_LOOT_Verigan's Fist|r)" },
        { "target", name = "Jordan Stilwell" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "Class quest: Poisons (Alliance)" },
        { "text", text = "Mathias and the Defias" },
        { "text", text = "At 20 |cOXP_FRIENDLY_Master Mathias Shaw|r, upstairs in the SI:7 building in |cOXP_PICK_Old Town|r, sends you to |cOXP_FRIENDLY_Agent Kearnen|r in Westfall. This chain is how you learn Poisons on Forever, so do not skip it." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 78.31, y = 70.74, zone = "1453" },
        { "accept", quest = 2360, text = "Accept Mathias and the Defias" },
        { "target", name = "Master Mathias Shaw" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "|cOXP_FRIENDLY_Agent Kearnen|r" },
        { "text", text = "Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of |cOXP_FRIENDLY_Klaven Mortwake|r's Defias tower in the far east of Westfall, by the Duskwood border. Read |cOXP_LOOT_Kearnen's Journal|r for the tower's layout if you like." },
        { "goto", x = 68.49, y = 70.08, zone = "1436" },
        { "turnin", quest = 2360, text = "Turn in Mathias and the Defias" },
        { "target", name = "Agent Kearnen" },
        { "goto", x = 68.49, y = 70.08, zone = "1436" },
        { "accept", quest = 2359, text = "Accept Klaven's Tower" },
        { "target", name = "Agent Kearnen" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "The |cOXP_LOOT_Defias Tower Key|r" },
        { "text", text = "Get the key first. The |cOXP_ENEMY_Malformed Defias Drone|r (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and Pick Pocket it from behind: it always has the key. It hits hard: if stealth breaks, Sprint away. Watch for the pair of Defias Drones that also patrol." },
        { "goto", x = 69.47, y = 73.99, zone = "1436" },
        { "complete", obj = 2, quest = 2359, text = "Defias Tower Key: 1" },
        { "mob", name = "Malformed Defias Drone" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "Klaven's journal" },
        { "text", text = "Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. |cOXP_FRIENDLY_Klaven Mortwake|r, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The |cOXP_PICK_Duskwood Chest|r beside his desk needs Lockpicking of about 70-75 (practise on the boxes at Alther's Mill in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the Touch of Zanzil, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out." },
        { "goto", x = 70.4, y = 74, zone = "1436" },
        { "complete", obj = 1, quest = 2359, text = "Klaven Mortwake's Journal: 1 (|cOXP_LOOT_Klaven Mortwake's Journal|r: the |cOXP_PICK_Duskwood Chest|r, top floor)" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "|cOXP_FRIENDLY_Master Mathias Shaw|r" },
        { "text", text = "Head north through Elwynn to Stormwind; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the |cOXP_LOOT_Thistle Tea|r recipe. Poisons are made, not bought: each batch of Instant Poison takes a |cOXP_LOOT_Dust of Decay|r and an |cOXP_LOOT_Empty Vial|r, which |cOXP_FRIENDLY_Jasper Fel|r and |cOXP_FRIENDLY_Sloan McCoy|r sell in |cOXP_PICK_Old Town|r next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon." },
        { "goto", x = 78.31, y = 70.74, zone = "1453" },
        { "turnin", quest = 2359, text = "Turn in Klaven's Tower (|cOXP_FRIENDLY_Master Mathias Shaw|r: Poisons)" },
        { "target", name = "Master Mathias Shaw" },
        { "goto", x = 78.31, y = 70.74, zone = "1453" },
        { "accept", quest = 2607, text = "Accept The Touch of Zanzil" },
        { "target", name = "Master Mathias Shaw" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "|cOXP_FRIENDLY_Doc Mixilpixil|r" },
        { "text", text = "The Touch of Zanzil still sits on you. |cOXP_FRIENDLY_Doc Mixilpixil|r works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind |cOXP_FRIENDLY_Jasper Fel|r. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down." },
        { "goto", x = 80.06, y = 69.9, zone = "1453" },
        { "turnin", quest = 2607, text = "Turn in The Touch of Zanzil" },
        { "target", name = "Doc Mixilpixil" },
        { "goto", x = 80.06, y = 69.9, zone = "1453" },
        { "accept", quest = 2608, text = "Accept The Touch of Zanzil" },
        { "target", name = "Doc Mixilpixil" },
        { "goto", x = 80.06, y = 69.9, zone = "1453" },
        { "finish", quest = 2608, text = "Finish The Touch of Zanzil: Diagnosis Complete (/lay with the Doc targeted)" },
        { "goto", x = 80.06, y = 69.9, zone = "1453" },
        { "turnin", quest = 2608, text = "Turn in The Touch of Zanzil" },
        { "target", name = "Doc Mixilpixil" },
        { "goto", x = 80.06, y = 69.9, zone = "1453" },
        { "accept", quest = 2609, text = "Accept The Touch of Zanzil" },
        { "target", name = "Doc Mixilpixil" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "The cure's ingredients" },
        { "text", text = "All four are in Stormwind. |cOXP_LOOT_Simple Wildflowers|r: Bernard or |cOXP_FRIENDLY_Felicia Gump|r's flower shop by the |cOXP_PICK_Trade District|r canal. A |cOXP_LOOT_Leaded Vial|r: many general goods and alchemy vendors (|cOXP_FRIENDLY_Keldric Boucher|r, |cOXP_FRIENDLY_Jasper Fel|r and others). A |cOXP_LOOT_Bronze Tube|r: the Auction House in the |cOXP_PICK_Trade District|r; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The |cOXP_LOOT_Spool of Light Chartreuse Silk Thread|r lies on the floor beside the left end of the counter in |cOXP_PICK_The Finest Thread|r, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an |cOXP_LOOT_Anti-Venom|r (First Aid) or a druid's Cure Poison also clears the Touch of Zanzil." },
        { "item", item = 3421, text = "Buy 1 Simple Wildflowers from |cOXP_FRIENDLY_None|r" },
        { "item", item = 3372, text = "Buy 1 Leaded Vial from |cOXP_FRIENDLY_None|r" },
        { "goto", x = 61.2, y = 71.3, zone = "1453" },
        { "item", item = 4371, text = "Bronze Tube: 1 (|cOXP_LOOT_Bronze Tube|r: the Auction House)" },
        { "goto", x = 50.58, y = 60.14, zone = "1453" },
        { "complete", obj = 4, quest = 2609, text = "Spool of Light Chartreuse Silk Thread: 1" },
      },
      { only = "Rogue", source = "polestar:forever/class/rogue/poisons-alliance",
        { "text", text = "Back to |cOXP_FRIENDLY_Doc Mixilpixil|r" },
        { "goto", x = 80.06, y = 69.9, zone = "1453" },
        { "turnin", quest = 2609, text = "Turn in The Touch of Zanzil (|cOXP_FRIENDLY_Doc Mixilpixil|r: |cOXP_LOOT_Eau de Mixilpixil|r)" },
        { "target", name = "Doc Mixilpixil" },
      },
      { only = "Gnome Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "Class quest: Succubus and Incubus (Alliance)" },
        { "text", text = "Gakin's Summons (Gnomes)" },
        { "text", text = "At 20 |cOXP_FRIENDLY_Lago Blackwrench|r, the warlock trainer in Ironforge's |cOXP_PICK_Forlorn Cavern|r, sends you to |cOXP_FRIENDLY_Gakin the Darkbinder|r in Stormwind. Take the Deeprun Tram." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 47.63, y = 9.26, zone = "1455" },
        { "accept", quest = 1717, text = "Accept Gakin's Summons" },
        { "target", name = "Lago Blackwrench" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "Devourer of Souls" },
        { "text", text = "At 20 |cOXP_FRIENDLY_Gakin the Darkbinder|r, in the cellar of the |cOXP_PICK_Slaughtered Lamb|r in the |cOXP_PICK_Mage Quarter|r, sends you to |cOXP_FRIENDLY_Takar the Seer|r in the Barrens: a long trip for the Alliance. Take the boat from Menethil Harbor to Theramore and head west through Dustwallow Marsh, or the boat from Booty Bay to Ratchet." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", only = "Gnome", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", only = "Gnome", quest = 1717, text = "Turn in Gakin's Summons" },
        { "target", name = "Gakin the Darkbinder", only = "Gnome" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "accept", quest = 1716, text = "Accept Devourer of Souls" },
        { "target", name = "Gakin the Darkbinder" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "|cOXP_FRIENDLY_Takar the Seer|r" },
        { "text", text = "|cOXP_FRIENDLY_Takar the Seer|r camps at a tent with a campfire just north-east of Camp Taurajo, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. |cOXP_FRIENDLY_Doan Karhan|r beside him starts the |cOXP_LOOT_Orb of Soran'ruk|r. Takar offers both branches: take both." },
        { "goto", x = 49.31, y = 57.1, zone = "1413" },
        { "turnin", quest = 1716, text = "Turn in Devourer of Souls" },
        { "target", name = "Takar the Seer" },
        { "goto", x = 49.31, y = 57.1, zone = "1413" },
        { "accept", quest = 1738, text = "Accept Heartswood (the succubus)" },
        { "target", name = "Takar the Seer" },
        { "goto", x = 49.31, y = 57.1, zone = "1413" },
        { "accept", quest = 65602, text = "Accept What Is Love? (the incubus)" },
        { "target", name = "Takar the Seer" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "Heartswood" },
        { "text", text = "Ordil'Aran lies in north-west Ashenvale, north of Astranaar along the road toward Darkshore. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the Heartswood from as far away as it lets you. It is turned in to |cOXP_FRIENDLY_Gakin the Darkbinder|r, not to Takar." },
        { "goto", x = 31.55, y = 31.57, zone = "1440" },
        { "complete", obj = 1, quest = 1738, text = "Heartswood: 1" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "The |cOXP_LOOT_Wooden Figurine|r" },
        { "text", text = "The house stands alone in the trees of north-western Ashenvale, north-west of Ordil'Aran and well north of Maestra's Post: do it on the same trip as the Heartswood. Take the |cOXP_LOOT_Unlit Torch|r from the table outside, light it at a campfire (a |cOXP_PICK_Basic Campfire|r of your own, or Talen's fire on Zoram Strand), and go straight back: the |cOXP_LOOT_Burning Torch|r burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs." },
        { "goto", x = 26.79, y = 22.43, zone = "1440" },
        { "item", count = 1, item = 190307, text = "Unlit Torch: 1 (|cOXP_LOOT_Unlit Torch|r, on the table outside)" },
        { "goto", x = 26.61, y = 22.03, zone = "1440" },
        { "complete", obj = 1, quest = 65602, text = "Wooden Figurine: 1 (|cOXP_LOOT_Wooden Figurine|r, upstairs)" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "The Binding: succubus" },
        { "text", text = "Back to |cOXP_FRIENDLY_Gakin the Darkbinder|r with the Heartswood. He hands you the |cOXP_LOOT_Heartswood Core|r: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, |cOXP_FRIENDLY_Gakin the Darkbinder|r takes it back." },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", quest = 1738, text = "Turn in Heartswood" },
        { "target", name = "Gakin the Darkbinder" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "accept", quest = 1739, text = "Accept The Binding" },
        { "target", name = "Gakin the Darkbinder" },
        { "goto", x = 39.1, y = 84.4, zone = "1453" },
        { "item", item = 6913, text = "Use Heartswood Core (|cOXP_LOOT_Heartswood Core|r, on the circle in the crypt)" },
        { "goto", x = 25.1, y = 77.4, zone = "1453" },
        { "complete", obj = 1, quest = 1739, text = "Kill Summoned Succubus: 1" },
        { "mob", name = "Summoned Succubus" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", quest = 1739, text = "Turn in The Binding (|cOXP_FRIENDLY_Gakin the Darkbinder|r: Summon Succubus)" },
        { "target", name = "Gakin the Darkbinder" },
      },
      { only = "Warlock", source = "polestar:forever/class/warlock/incubus-alliance",
        { "text", text = "The Binding: incubus" },
        { "text", text = "Give Gakin the figurine, then use the |cOXP_LOOT_Wooden Figurine|r at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: |cOXP_FRIENDLY_Gakin the Darkbinder|r takes it back." },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", quest = 65602, text = "Turn in What Is Love?" },
        { "target", name = "Gakin the Darkbinder" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "accept", quest = 65603, text = "Accept The Binding" },
        { "target", name = "Gakin the Darkbinder" },
        { "goto", x = 39.04, y = 84.64, zone = "1453" },
        { "complete", obj = 1, quest = 65603, text = "Kill Summoned Incubus: 1 (|cOXP_ENEMY_Summoned Incubus|r, at the circle in the crypt)" },
        { "mob", name = "Summoned Incubus" },
        { "goto", x = 39.22, y = 85.23, zone = "1453" },
        { "turnin", quest = 65603, text = "Turn in The Binding (|cOXP_FRIENDLY_Gakin the Darkbinder|r: Summon Incubus)" },
        { "target", name = "Gakin the Darkbinder" },
      },
      { only = "Human Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Class quest: Fire Hardened Armor" },
        { "text", text = "Yorus Barleybrew (Stormwind)" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Wu Shen|r, beside |cOXP_FRIENDLY_Ilsa Corbin|r in the warrior trainers' building of |cOXP_PICK_Old Town|r, sends you to Yorus Barleybrew in Redridge." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 80.55, y = 59.87, zone = "1453" },
        { "accept", quest = 1698, text = "Accept Yorus Barleybrew" },
        { "target", name = "Wu Shen" },
      },
      { only = "Dwarf Warrior/Gnome Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Yorus Barleybrew (Ironforge)" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Kelv Sternhammer|r, the warrior trainer of Ironforge, sends you to Yorus Barleybrew in Redridge." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 70.34, y = 90.65, zone = "1455" },
        { "accept", quest = 1698, text = "Accept Yorus Barleybrew" },
        { "target", name = "Kelv Sternhammer" },
      },
      { only = "NightElf Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Yorus Barleybrew (Darnassus)" },
        { "text", text = "At 20, |cOXP_FRIENDLY_Darnath Bladesinger|r, the warrior trainer of Darnassus, sends you to Yorus Barleybrew in Redridge." },
        { "xp", level = 20, text = "Reach level 20" },
        { "goto", x = 58.94, y = 35.35, zone = "1457" },
        { "accept", quest = 1698, text = "Accept Yorus Barleybrew" },
        { "target", name = "Darnath Bladesinger" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Yorus Barleybrew" },
        { "text", text = "Yorus Barleybrew sits in the inn at Lakeshire. His test is timed: before you take it, clear the Redridge gnolls on the path to the Rethban Caverns in the hills north-west of Lakeshire, including the two on the rock by the cave mouth (climb it from its right side)." },
        { "goto", x = 21.49, y = 44.72, zone = "1433" },
        { "turnin", quest = 1698, text = "Turn in Yorus Barleybrew" },
        { "target", name = "Yorus Barleybrew" },
        { "goto", x = 21.49, y = 44.72, zone = "1433" },
        { "accept", quest = 1699, text = "Accept The Rethban Gauntlet" },
        { "target", name = "Yorus Barleybrew" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "The Rethban Gauntlet" },
        { "text", text = "You have one hour, and |cOXP_FRIENDLY_Yorus Barleybrew|r's Barleybrew Scalder leaves you drunk for 8-10 minutes. Run north-west into the Rethban Caverns, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to |cOXP_FRIENDLY_Yorus Barleybrew|r (from the ridge you can jump down into Lakeshire). Dying and releasing your spirit fails the quest: abandon it and |cOXP_FRIENDLY_Yorus Barleybrew|r gives it again." },
        { "finish", quest = 1699, text = "Finish The Rethban Gauntlet: Enter the Rethban Caverns (Enter the Rethban Caverns and come back)" },
        { "goto", x = 21.49, y = 44.72, zone = "1433" },
        { "turnin", quest = 1699, text = "Turn in The Rethban Gauntlet" },
        { "target", name = "Yorus Barleybrew" },
        { "goto", x = 21.49, y = 44.72, zone = "1433" },
        { "accept", quest = 1702, text = "Accept The Shieldsmith" },
        { "target", name = "Yorus Barleybrew" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "The Shieldsmith" },
        { "text", text = "|cOXP_FRIENDLY_Furen Longbeard|r works in the Dwarven District of Stormwind. He takes the |cOXP_LOOT_Cask of Scalder|r (lost it? abandon the quest and |cOXP_FRIENDLY_Yorus Barleybrew|r gives a new one) and gives you |cOXP_LOOT_Furen's Favor|r, a shield; Fire Hardened Mail is a level 28 quest, with |cOXP_LOOT_Furen's Instructions|r listing what it needs." },
        { "goto", x = 64.62, y = 37.23, zone = "1453" },
        { "turnin", quest = 1702, text = "Turn in The Shieldsmith" },
        { "target", name = "Furen Longbeard" },
        { "goto", x = 64.62, y = 37.23, zone = "1453" },
        { "accept", quest = 1701, text = "Accept Fire Hardened Mail" },
        { "target", name = "Furen Longbeard" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Scorched Spider Fangs" },
        { "text", text = "You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the Wetlands, north of Dun Algaz; every one drops a fang. They poison; back in 5 minutes." },
        { "goto", x = 52.65, y = 63.09, zone = "1437" },
        { "complete", obj = 1, quest = 1701, text = "Scorched Spider Fang: 50" },
        { "mob", name = "Leech Stalker" },
        { "mob", name = "Cave Stalker" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Charred and Galvanized Horns" },
        { "text", text = "The chimaeras live south-west of Sun Rock Retreat in the Charred Vale; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the |cOXP_LOOT_Galvanized Horn|r from the |cOXP_ENEMY_Chimaera Matriarch|r (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit Corrosive Poison, the Young cast Lightning Bolt. Alliance: fly to Stonetalon Peak and head south." },
        { "xp", level = 26, text = "Reach level 26" },
        { "goto", x = 32.99, y = 72.07, zone = "1442" },
        { "complete", obj = 2, quest = 1701, text = "Charred Horn: 12 (|cOXP_LOOT_Charred Horn|r, from the young chimaeras)" },
        { "mob", name = "Fledgling Chimaera" },
        { "mob", name = "Young Chimaera" },
        { "goto", x = 33.64, y = 74.66, zone = "1442" },
        { "complete", obj = 3, quest = 1701, text = "Galvanized Horn: 1 (|cOXP_LOOT_Galvanized Horn|r, from the |cOXP_ENEMY_Chimaera Matriarch|r)" },
        { "mob", name = "Chimaera Matriarch" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Roogug in Razorfen Kraul" },
        { "text", text = "Roogug is an elite quilboar (level 28) inside Razorfen Kraul, the dungeon at the south end of the Barrens; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts Lightning Bolt and calls Earth Rumblers. The vial always drops." },
        { "goto", x = 42.9, y = 90.2, zone = "1413" },
        { "complete", obj = 4, quest = 1701, text = "Vial of Phlogiston: 1 (|cOXP_LOOT_Vial of Phlogiston|r, from Roogug)" },
      },
      { only = "Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Furen's Armor" },
        { "text", text = "Back to |cOXP_FRIENDLY_Furen Longbeard|r in the |cOXP_PICK_Dwarven District|r for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly." },
        { "goto", x = 64.62, y = 37.23, zone = "1453" },
        { "turnin", quest = 1701, text = "Turn in Fire Hardened Mail" },
        { "target", name = "Furen Longbeard" },
