      { only = "Human Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "|cOXP_FRIENDLY_Grimand Elmore|r" },
        { "text", text = "|cOXP_FRIENDLY_Grimand Elmore|r keeps the weapon shop in the north-west of the |cOXP_PICK_Dwarven District|r, a short walk from |cOXP_FRIENDLY_Furen Longbeard|r. He wants 20 Burning Blood and the |cOXP_LOOT_Burning Rock|r." },
        { "goto", only = "Human", x = 59.73, y = 33.78, zone = "1453" },
        { "turnin", only = "Human", quest = 1700, text = "Turn in Grimand Elmore" },
