      },
      { only = "Human Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Burning Blood" },
        { "text", text = "The Nightbane worgen of Duskwood (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of Darkshire drop the Burning Blood four kills in five. The Tainted Ones poison and howl; Vile Fangs cause Infected Wound." },
        { "goto", x = 64.05, y = 58.91, zone = "1431" },
        { "complete", obj = 1, quest = 1705, text = "Burning Blood: 20 (Burning Blood, from the Nightbane worgen)" },
        { "mob", name = "Nightbane Dark Runner" },
        { "mob", name = "Nightbane Vile Fang" },
        { "mob", name = "Nightbane Shadow Weaver" },
      },
      { only = "Human Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "|cOXP_ENEMY_Gutspill|r" },
        { "text", text = "|cOXP_ENEMY_Gutspill|r (level 32, not elite) carries the |cOXP_LOOT_Burning Rock|r, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the Roland's Doom mine south-east of Darkshire, so wait at the entrance and pull him outside. He poisons and howls." },
        { "xp", level = 30, text = "Reach level 30" },
        { "goto", x = 73.89, y = 77.17, zone = "1431" },
