      { only = "Dwarf Warrior/Gnome Warrior", source = "polestar:forever/class/warrior/fire-hardened-armor",
        { "text", text = "Iron Coral" },
        { "text", text = "The Iron Coral grows on the sea floor just south of Menethil Harbor, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a |cOXP_LOOT_Draught of Water Breathing|r removes the risk." },
        { "goto", x = 9.31, y = 69.14, zone = "1437" },
