      { only = "Paladin", source = "polestar:forever/class/paladin/cloak-of-the-divine-storm",
        { "text", text = "|cOXP_FRIENDLY_Katherine the Pure|r" },
        { "text", text = "|cOXP_FRIENDLY_Katherine the Pure|r stands in the Cathedral of Light; she sends you to a warlock for a second opinion." },
