      { only = "Paladin", source = "polestar:forever/class/paladin/cloak-of-the-divine-storm",
        { "text", text = "|cOXP_FRIENDLY_Ursula Deline|r" },
        { "text", text = "|cOXP_FRIENDLY_Ursula Deline|r, the warlock trainer, is in the |cOXP_PICK_Mage Quarter|r's warlock sanctum, down in the |cOXP_PICK_Slaughtered Lamb|r's cellar. She wants 14 |cOXP_LOOT_Summoner's Salt|r to read the orb." },
