        { "target", name = "Ursula Deline" },
        { "goto", x = 39.89, y = 84.19, zone = "1453" },
        { "accept", quest = 78091, text = "Accept Earning Your Salt" },
        { "target", name = "Ursula Deline" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/cloak-of-the-divine-storm",
        { "text", text = "|cOXP_LOOT_Summoner's Salt|r" },
        { "text", text = "The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the |cOXP_LOOT_Summoner's Salt|r; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of Lakeshire drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is |cOXP_ENEMY_Gath'Ilzogg|r (26): stay in the north-west." },
        { "goto", x = 23.5, y = 12, zone = "1433" },
        { "complete", obj = 1, quest = 78091, text = "Summoner's Salt: 14" },
        { "mob", name = "Blackrock Summoner" },
