      { only = "Paladin", source = "polestar:forever/class/paladin/cloak-of-the-divine-storm",
        { "text", text = "Motes of Mannoroth" },
        { "text", text = "Demon Fall Canyon is in south-east Ashenvale, east of Splintertree Post (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast Shadow Bolt and Immolate, Infernals keep a fire shield up. They respawn in five minutes." },
        { "goto", x = 78.48, y = 81.61, zone = "1440" },
        { "complete", obj = 1, quest = 78092, text = "Mote of Mannoroth: 12" },
        { "mob", name = "Legion Hound" },
        { "mob", name = "Searing Infernal" },
        { "mob", name = "Felguard" },
      },
      { only = "Paladin", source = "polestar:forever/class/paladin/cloak-of-the-divine-storm",
        { "text", text = "The |cOXP_PICK_Spear of Mannoroth|r" },
        { "text", text = "The |cOXP_PICK_Spear of Mannoroth|r stands at the east end of Demon Fall Canyon. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the |cOXP_PICK_Shattered Orb|r beside it starts the last quest." },
        { "goto", x = 89.4, y = 77.1, zone = "1440" },
        { "turnin", quest = 78092, text = "Turn in It Must Be Destroyed" },
        { "goto", x = 89.4, y = 77, zone = "1440" },
        { "accept", quest = 78093, text = "Accept Return to Delgren (from the |cOXP_PICK_Shattered Orb|r)" },
      },
